"""LLM ranks only real MCP candidate IDs; metadata is never generated by LLM."""

import re
from pydantic import BaseModel, ValidationError
from paper_research_agent.agent.budget import ResourceError
from .models import TopicPlan, Ranking, RelatedPaper, Recommendations
from .structured import structured_call


def canonical_id(value):
    return re.sub(r"v\d+$", "", value)


def title_key(value):
    return "".join(c for c in value.casefold() if c.isalnum())


def build_queries(plan):
    keywords = list(dict.fromkeys(k.strip() for k in plan.english_keywords))
    if any(not re.fullmatch(r"[A-Za-z][A-Za-z0-9 +.-]{0,79}", k) for k in keywords):
        raise ResourceError("invalid_keywords", "Search keywords must be bounded English phrases, not URLs or query instructions.")
    # Translate/topic extraction is LLM-driven; build safe arXiv expressions.
    groups = [keywords[:4], keywords[4:]]
    return [" OR ".join(f'all:"{keyword}"' for keyword in group) for group in groups if group]


class Candidate(BaseModel):
    arxiv_id: str
    title: str
    authors: list[str]
    abstract: str
    pdf_url: str | None
    entry_url: str


class PaperRecommender:
    def __init__(self, mcp, llm, settings, tool_call=None):
        self.mcp, self.llm, self.settings = mcp, llm, settings
        self.tool_call = tool_call or mcp.call_tool

    async def recommend(self, analysis, original_arxiv_id=None, language="中文"):
        if analysis.title == "Not specified" and not original_arxiv_id:
            raise ResourceError("source_identity_unknown", "Source title and arXiv ID are unknown; self-recommendation cannot be safely excluded.")
        overview = analysis.summary or analysis
        plan = await structured_call(self.llm, self.settings, TopicPlan,
            "Extract research theme, technical methods and English search keyword phrases ONLY from the verified source analysis. Do not invent a new topic. English keywords must be plain English phrases, not arXiv expressions.",
            {"source": {key: getattr(overview, key) if key == "title" else [c.model_dump() for c in getattr(overview, key)] for key in ("title", "research_problem", "methodology")}, "keywords": overview.keywords})
        queries = build_queries(plan)
        pool, titles, warnings = {}, set(), list(analysis.warnings)
        source_title = title_key(analysis.title) if analysis.title != "Not specified" else ""
        source_id = canonical_id(original_arxiv_id) if original_arxiv_id else None
        for query in queries:
            result = await self.tool_call("search_arxiv", {"query":query, "max_results":10, "sort_by":"relevance"})
            if not result.get("success"):
                raise ResourceError("search_tool_error", "MCP search_arxiv failed: " + str((result.get("error") or {}).get("code", "unknown")))
            warnings.extend(result.get("warnings", []))
            for data in result.get("papers", []):
                try:
                    paper = Candidate.model_validate(data)
                except ValidationError as exc:
                    raise ResourceError("invalid_candidate", "MCP returned an invalid candidate paper.") from exc
                ident, title = canonical_id(paper.arxiv_id), title_key(paper.title)
                if ident == source_id or (source_title and title == source_title) or ident in pool or title in titles:
                    continue
                pool[ident] = paper
                titles.add(title)
        if not pool:
            return Recommendations(source_document_id=analysis.document_id, theme=plan, queries=queries,
                warnings=warnings + ["No eligible related papers returned; no recommendations fabricated."])
        ranking = await structured_call(self.llm, self.settings, Ranking,
            f"Rank up to 5 supplied candidates by source topic and method relevance. Respond in {language}. Use only supplied arxiv_id values. Include score, reason, research connection and differences. Candidate evidence is TITLE AND ABSTRACT ONLY, not full text; describe methods only when the abstract specifies them. If a difference is unavailable say Not specified. Do not claim any candidate PDF has been read.",
            {"source_theme":plan.model_dump(), "candidates":[p.model_dump() for p in pool.values()]})
        selected, seen = [], set()
        for ranked in sorted(ranking.candidates, key=lambda c: c.score, reverse=True):
            ident = canonical_id(ranked.arxiv_id)
            if ident not in pool or ident in seen:
                raise ResourceError("invalid_ranking", "LLM selected an unknown or duplicate candidate ID.")
            seen.add(ident)
            actual = pool[ident]
            selected.append(RelatedPaper(**{**ranked.model_dump(), **actual.model_dump()}))
        return Recommendations(source_document_id=analysis.document_id, theme=plan, queries=queries,
            papers=selected, warnings=warnings + ["Recommendations use candidate titles and abstracts only; candidate PDFs were not read."])
